<section class="panel"><div class="panel-head"><div><span class="panel-kicker">تنظيم العمل</span><h2>الملاحظات والمهام</h2></div></div>
<form method="post" action="/admin/notes/save" class="form-grid note-create-card"><?=csrf_field()?>
<label class="span-2">العنوان<input name="title" required placeholder="مثال: مراجعة المقالات المعلقة"></label>
<label>الأولوية<select name="priority"><option value="normal">عادي</option><option value="important">مهم</option><option value="urgent">عاجل</option></select></label>
<label>الحالة<select name="status"><option value="new">جديدة</option><option value="doing">قيد التنفيذ</option><option value="done">مكتملة</option></select></label>
<label>تعيين إلى<select name="assigned_to"><option value="">بدون تعيين</option><?php foreach($assignees as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></label>
<?php if($fullAdmin):?><label>الظهور<select name="visibility"><option value="admin">المدير فقط</option><option value="management">المدير ومساعد المدير</option></select></label><?php else:?><input type="hidden" name="visibility" value="management"><?php endif;?>
<label>موعد التذكير<input type="datetime-local" name="due_at"></label><label class="check-line"><input type="checkbox" name="pinned" value="1"> تثبيت أعلى القائمة</label>
<label class="span-2">التفاصيل<textarea name="body" rows="4"></textarea></label><button class="btn btn-primary span-2">إضافة الملاحظة</button></form>
<div class="notes-board"><?php foreach($notes as $n):?><article class="note-card p-<?=e($n['priority'])?> s-<?=e($n['status'])?>"><div class="note-card-head"><div><strong><?=e($n['title'])?></strong><small><?=e($n['creator_name'])?><?=!empty($n['assigned_name'])?' ← '.e($n['assigned_name']):''?></small></div><span><?=e($n['priority'])?></span></div><p><?=nl2br(e($n['body']??''))?></p><?php if($n['due_at']):?><small>موعد: <?=e($n['due_at'])?></small><?php endif;?><div class="note-actions"><form method="post" action="/admin/notes/save"><?=csrf_field()?><input type="hidden" name="id" value="<?=$n['id']?>"><input type="hidden" name="title" value="<?=e($n['title'])?>"><input type="hidden" name="body" value="<?=e($n['body']??'')?>"><input type="hidden" name="priority" value="<?=e($n['priority'])?>"><input type="hidden" name="visibility" value="<?=e($n['visibility'])?>"><select name="status"><option value="new" <?=$n['status']==='new'?'selected':''?>>جديدة</option><option value="doing" <?=$n['status']==='doing'?'selected':''?>>قيد التنفيذ</option><option value="done" <?=$n['status']==='done'?'selected':''?>>مكتملة</option></select><button class="btn btn-ghost">تحديث</button></form><form method="post" action="/admin/notes/delete" onsubmit="return confirm('حذف الملاحظة؟')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$n['id']?>"><button class="btn btn-danger">حذف</button></form></div></article><?php endforeach;?></div></section>
